{
  "name": "opencode-add-dir",
  "version": "1.8.0",
  "description": "Add working directories to your OpenCode session with auto-approved permissions",
  "author": "Cristian Fonseca <cfonsecacomas@gmail.com>",
  "type": "module",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    },
    "./server": {
      "import": "./dist/index.js"
    },
    "./tui": {
      "import": "./dist/tui.js"
    }
  },
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "oc-plugin": [
    "server",
    "tui"
  ],
  "files": [
    "dist/",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "build": "rm -rf dist && bun run build:server && bun run build:tui && bun x tsc --emitDeclarationOnly",
    "build:server": "bun build ./src/index.ts --outdir ./dist --target node --format esm --external @opencode-ai/plugin --external @opencode/plugin --minify",
    "build:tui": "bun run ./scripts/build-tui.ts",
    "deploy": "rm -rf dist && bun run build:server && bun run build:tui",
    "test": "bun test",
    "typecheck": "bun x tsc --project tsconfig.check.json",
    "prepublishOnly": "bun run typecheck && bun test && bun run build"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "add-dir",
    "working-directory",
    "permissions"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/0xkuze/add-dir-opencode.git"
  },
  "license": "MIT",
  "dependencies": {
    "@opencode/plugin": "^2.0.16"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.0.0",
    "@opentui/core": ">=0.1.92",
    "@opentui/solid": ">=0.1.92"
  },
  "peerDependenciesMeta": {
    "@opentui/core": {
      "optional": true
    },
    "@opentui/solid": {
      "optional": true
    }
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.1.14",
    "@opentui/core": "0.1.95",
    "@opentui/solid": "0.1.95",
    "@semantic-release/changelog": "^6.0.3",
    "@semantic-release/commit-analyzer": "^13.0.1",
    "@semantic-release/git": "^10.0.1",
    "@semantic-release/github": "^12.0.6",
    "@semantic-release/npm": "^13.1.5",
    "@semantic-release/release-notes-generator": "^14.1.0",
    "@types/bun": "latest",
    "semantic-release": "^25.0.3",
    "solid-js": "^1.9.12",
    "typescript": "^5.8.3"
  }
}
